create table if not exists public.blog_owner(id uuid primary key); insert into public.blog_owner select id from auth.users order by created_at limit 1 on conflict do nothing; alter table public.blog_owner enable row level security; create or replace function public.is_blog_owner() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.blog_owner where id=auth.uid()) $$; create table if not exists public.posts(id uuid primary key default gen_random_uuid(), title text not null default '', body text not null default '', published boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now()); alter table public.posts enable row level security; drop policy if exists "posts read" on public.posts; drop policy if exists "posts write" on public.posts; create policy "posts read" on public.posts for select using (published or public.is_blog_owner()); create policy "posts write" on public.posts for all to authenticated using (public.is_blog_owner()) with check (public.is_blog_owner()); insert into storage.buckets(id,name,public,file_size_limit) values('blog','blog',true,10485760) on conflict(id) do update set public=true; drop policy if exists "blog img read" on storage.objects; drop policy if exists "blog img write" on storage.objects; drop policy if exists "blog img delete" on storage.objects; create policy "blog img read" on storage.objects for select using (bucket_id='blog'); create policy "blog img write" on storage.objects for insert to authenticated with check (bucket_id='blog' and public.is_blog_owner()); create policy "blog img delete" on storage.objects for delete to authenticated using (bucket_id='blog' and public.is_blog_owner());
